// One folder per client, plus a welcome doc from a template.
const fs = require('fs');
const path = require('path');
const base = $env.EP09_DIR;
const j = $input.first().json;

const slug = j['Company name'].toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '');
const dir = path.join(base, 'clients', slug);
fs.mkdirSync(dir, { recursive: true });

let doc = fs.readFileSync(path.join(base, 'templates', 'welcome-template.md'), 'utf8');
doc = doc.replace(/{{company}}/g, j['Company name'])
  .replace(/{{contact}}/g, j['Contact name'])
  .replace(/{{goal}}/g, j['Main goal for the first 90 days'])
  .replace(/{{kickoff}}/g, String(j['Kickoff date']).slice(0, 10));
fs.writeFileSync(path.join(dir, 'welcome.md'), doc);

j.slug = slug;
j.dir = dir;
return $input.all();

// Contract from a template. SAMPLE ribbon stays in — fictional client, fictional terms.
const fs = require('fs');
const path = require('path');
const base = $env.EP09_DIR;
const j = $input.first().json;

let html = fs.readFileSync(path.join(base, 'templates', 'contract-template.html'), 'utf8');
html = html.replace(/{{company}}/g, j['Company name'])
  .replace(/{{contact}}/g, j['Contact name'])
  .replace(/{{project}}/g, j['Project type'])
  .replace(/{{kickoff}}/g, String(j['Kickoff date']).slice(0, 10))
  .replace(/{{date_today}}/g, new Date().toISOString().slice(0, 10));
fs.writeFileSync(path.join(j.dir, 'contract.html'), html);
return $input.all();

// A real calendar invite: 45 minutes, 10:00 local, on the kickoff date.
const fs = require('fs');
const path = require('path');
const j = $input.first().json;

const d = String(j['Kickoff date']).slice(0, 10).replace(/-/g, '');
const ics = [
  'BEGIN:VCALENDAR', 'VERSION:2.0', 'PRODID:-//Northgate Labs//Onboarding//EN',
  'BEGIN:VEVENT', 'UID:' + j.slug + '-kickoff@shipsitself.local',
  'DTSTART:' + d + 'T100000', 'DTEND:' + d + 'T104500',
  'SUMMARY:Kickoff - ' + j['Company name'],
  'DESCRIPTION:First 90 days: ' + j['Main goal for the first 90 days'].replace(/\n/g, ' '),
  'END:VEVENT', 'END:VCALENDAR',
].join('\r\n');
fs.writeFileSync(path.join(j.dir, 'kickoff.ics'), ics);
return $input.all();

// One CRM: a CSV I can open, sort, and grep. Header written on first run.
const fs = require('fs');
const path = require('path');
const base = $env.EP09_DIR;
const j = $input.first().json;

const file = path.join(base, 'crm', 'crm.csv');
if (!fs.existsSync(file)) {
  fs.writeFileSync(file, 'Company,Contact,Email,Project,Kickoff,Status,Created\n');
}
const esc = (v) => '"' + String(v).replace(/"/g, '""') + '"';
const row = [
  j['Company name'], j['Contact name'], j['Contact email'], j['Project type'],
  String(j['Kickoff date']).slice(0, 10), 'Onboarding', new Date().toISOString(),
].map(esc).join(',');
fs.appendFileSync(file, row + '\n');
return $input.all();

// Task checklist with real dates: T+1, T+3, T+7 from kickoff.
const fs = require('fs');
const path = require('path');
const base = $env.EP09_DIR;
const j = $input.first().json;

const kick = String(j['Kickoff date']).slice(0, 10);
const plus = (n) => {
  const t = new Date(kick);
  t.setDate(t.getDate() + n);
  return t.toISOString().slice(0, 10);
};
let md = fs.readFileSync(path.join(base, 'templates', 'checklist-template.md'), 'utf8');
md = md.replace(/{{company}}/g, j['Company name'])
  .replace(/{{contact}}/g, j['Contact name'])
  .replace(/{{kickoff}}/g, kick)
  .replace(/{{t1}}/g, plus(1)).replace(/{{t3}}/g, plus(3)).replace(/{{t7}}/g, plus(7));
fs.writeFileSync(path.join(j.dir, 'tasks.md'), md);
return $input.all();
